$.fn.noticeBox = function (command) {
  return this.each(function () {
    const $item = $(this);
    if (command === "destroy") { $item.off(".noticeBox").removeData("noticeBox"); return; }
    $item.data("noticeBox", { initialized: true });
  });
};

